const context = $('Load published graph context').item.json;
const policy = $('Resolve conversation policy').item.json;
const binding = $('Validate conversation binding').item.json;
const contract = context.graph_contract || {};
const conversationPolicy = contract.conversation_policy || {};
const questions = contract.questions || {};

// What the customer has already been asked, and what is still open.
const legacyAskedIds = context.cart && context.cart.asked_question_node_ids || [];
const proofAskedKeys = context.cart && context.cart.asked_field_keys;
const askedFieldKeys = [...new Set(Array.isArray(proofAskedKeys) ? proofAskedKeys : legacyAskedIds.map(function (id) { return questions[id] && questions[id].field_key; }).filter(Boolean))];
const askedSet = new Set(askedFieldKeys);
const factsByKey = context.cart && context.cart.facts_by_key || {};
const unresolvedAskedFieldKeys = askedFieldKeys.filter(function (key) { return !Array.isArray(factsByKey[key]) || factsByKey[key].length === 0; });
const expectedAnswerFieldKey = unresolvedAskedFieldKeys.length ? unresolvedAskedFieldKeys[unresolvedAskedFieldKeys.length - 1] : null;
const doNotAskFieldKeys = [...new Set(askedFieldKeys)];

const fields = (contract.fields || []).map(function (field) {
  return { key: field.key, label: field.label || (contract.field_labels || {})[field.key] || field.key, owner_node_id: field.owner_node_id || null, required: field.required === true, depends_on: field.depends_on || [], validation: field.validation || {}, value_schema: field.value_schema || null, accepted_statuses: field.accepted_statuses || ['known'], already_asked: askedSet.has(field.key) };
});

// Vocabulary, read from the graph and never hardcoded, so each persona speaks
// its own language. A field's enum aliases are examples of how customers phrase
// that answer -- wording worth mirroring, never a list the answer has to match.
// Deciding which published value an answer means is the model's job, stated in
// policy.instructions; the aliases here only feed the persona's voice.
const vocabulary = { field_labels: conversationPolicy.field_labels || contract.field_labels || {}, answer_terms: {} };
for (const field of contract.fields || []) {
  const values = (field.validation || {}).values || [];
  const terms = [];
  for (const option of values) { for (const alias of option.aliases || []) { if (alias) terms.push(String(alias)); } }
  if (terms.length) vocabulary.answer_terms[field.key] = [...new Set(terms)];
}

// Evidence passes through whole. The template deliberately does no trimming:
// four contract tests pin `provider_managed`, because dropping a chunk here
// removes evidence the model needed without anyone seeing it. Bounding what is
// retrieved belongs to retrieval (roadmap P0), not to the prompt builder.
const tokenEstimate = function (value) { const text = typeof value === 'string' ? value : JSON.stringify(value); return Math.max(1, Math.ceil(text.length / 4)); };
const approvedNodes = (context.context_cards || []).map(function (card) { return { node_id: card.id, type: card.node_type, title: card.title, checksum: card.content_checksum, source: card.source, status: card.status }; });
const removedContext = [];
const approvedChunks = [];
let ragTokens = 0;
for (const chunk of (context.rag_chunks || [])) {
  const compact = { chunk_id: chunk.chunk_id || chunk.id, source_node_id: chunk.source_node_id || chunk.source_graph_node_id, kind: chunk.chunk_kind, text: chunk.chunk_text, checksum: chunk.chunk_checksum, path_checksum: chunk.path_checksum, provenance: chunk.metadata && chunk.metadata.provenance || {} };
  approvedChunks.push(compact); ragTokens += tokenEstimate(compact.text || '');
}

const rawMemory = context.shared_memory || {};
const recentMessages = (rawMemory.recent_messages || context.messages || []).slice(-6);
const isFirstAssistantTurn = !recentMessages.some(function (message) { const role = String(message.role || message.sender_type || '').toLowerCase(); return role === 'assistant' || role === 'agent' || role === 'ai'; });
const memory = { profile_facts: rawMemory.profile_facts || [], current_journey: rawMemory.current_journey || null, pending_items: rawMemory.pending_items || [], recent_messages: recentMessages, asked_field_keys: askedFieldKeys, last_handoff: context.last_handoff || null };

const schema = { type: 'object', additionalProperties: false, required: ['envelope_version','reply','facts','branch_selections','confirmation','customer_questions','claims','cited_node_ids','cited_chunk_ids','handoff_requested'], properties: { envelope_version: { const: '3' }, reply: { type: 'string' }, facts: { type: 'array', items: { type: 'object', additionalProperties: false, required: ['field_key','value','status','owner_node_id','evidence_span','source_message_id','metadata'], properties: { field_key: { type: 'string' }, value: {}, status: { enum: ['known','unknown','declined','needs_confirmation','invalid'] }, owner_node_id: { type: 'string' }, evidence_span: { type: 'string' }, source_message_id: { type: ['string','null'] }, metadata: { type: 'object' } } } }, branch_selections: { type: 'array', items: { type: 'object', additionalProperties: false, required: ['action','branch_anchor_node_id','evidence_span'], properties: { action: { enum: ['none','keep','select','switch','add','drop'] }, branch_anchor_node_id: { type: ['string','null'] }, evidence_span: { type: 'string' } } } }, confirmation: { type: 'object', additionalProperties: false, required: ['state','target_ref','evidence_span','correction_field_key','correction_value'], properties: { state: { enum: ['none','affirm','reject','partial','ambiguous'] }, target_ref: { type: ['string','null'] }, evidence_span: { type: 'string' }, correction_field_key: { type: ['string','null'] }, correction_value: {} } }, customer_questions: { type: 'array', items: { type: 'object', additionalProperties: false, required: ['kind','topic','entity_node_ids','evidence_span'], properties: { kind: { enum: ['availability','price','stock','policy','schedule','deadline','product_detail','other'] }, topic: { type: 'string' }, entity_node_ids: { type: 'array', items: { type: 'string' } }, evidence_span: { type: 'string' } } } }, claims: { type: 'array', items: { type: 'object', additionalProperties: false, required: ['claim_type','value','evidence_node_ids','evidence_chunk_ids'], properties: { claim_type: { type: 'string' }, value: { type: 'object' }, evidence_node_ids: { type: 'array', items: { type: 'string' } }, evidence_chunk_ids: { type: 'array', items: { type: 'string' } } } }, cited_node_ids: { type: 'array', items: { type: 'string' } }, cited_chunk_ids: { type: 'array', items: { type: 'string' } }, asked_field_key: { type: ['string','null'] }, handoff_requested: { type: 'boolean' } } } };

const prompt = { contract: 'conversation_envelope_v3', voice: { identity: context.system_prompt || '', guidelines: conversationPolicy.response_ownership || {}, opening: conversationPolicy.opening || {}, question_policy: conversationPolicy.question_policy || {}, doubt_handling: conversationPolicy.doubt_handling || {}, vocabulary: vocabulary }, policy: { instructions: ["Speak as the persona described in voice.identity, following voice.guidelines. Those are published by this persona's own graph and outrank any default habit of yours.", "On is_first_assistant_turn, introduce yourself once using the published AI identity in voice.opening. Be explicit that you are an AI/virtual assistant. Never repeat that introduction on later turns.", "Speak like a customer-facing agent. Never expose graph vocabulary such as node, branch, retrieval, published option, product group or service when the graph business model is sales; use the natural terms supplied by policy.rules.sales_routing and the customer instead.", "Use the words this business uses. voice.vocabulary lists its published terms; prefer them over synonyms you would reach for by default, and mirror the customer's own wording when they offer one.", "Answer and explain before qualifying.", "Use at most one useful question; a missing field never forces one.", "When qualification is incomplete and at least one unresolved graph field is eligible because its dependencies are satisfied, any question you choose to advance the conversation must ask exactly one of those eligible fields and asked_field_key must name it. You may recommend catalog options as statements, but never replace that eligible qualification question with an untracked product-selection or consultative question.", "Never repeat a known or already asked field. Treat do_not_ask_field_keys as a hard per-conversation prohibition: never ask any field in that list again and never return one of those keys as asked_field_key. If expected_answer_field_key is non-null and the customer changes branch or adds other information without answering it, acknowledge that new information without asking the pending field again. Ask no question unless a different eligible field has never been asked. Example: after you already asked the customer's name, if the customer says 'Actually it is for personal use', acknowledge the change but do not ask the name again; asked_field_key stays null unless you ask a different eligible never-asked field.", "Extract every declared fact the current customer message provides, even when it answers more than one field or volunteers a field you did not ask. If you ask a graph field, asked_field_key must be that exact field key; otherwise keep it null.", "Build facts before composing reply. Resolve expected_answer_field_key first: if customer_message answers it, facts must include that exact field in this envelope before you may acknowledge the answer or ask the next question.", "A value used or paraphrased in reply is necessarily understood: persist its matching graph field in facts. It is invalid to say a customer name, acknowledge comparing/deciding, or acknowledge shipping/store preference while omitting the corresponding fact.", "For enum fields emit the exact canonical value from validation.values and copy a literal evidence_span from customer_message. For human_full_name emit only the name as value, including when the message says call me X, my name is X, I am X, or answers with a bare name.", "Before returning, self-check: every answer supplied in customer_message is present in facts, and every qualification question has asked_field_key set to its exact eligible missing field. If either check fails, fix the JSON before returning it.", "Do not repeat a catalog explanation or offer of a photo already present in recent_messages. Add new useful information, move to another eligible topic, or request a human handoff with notice.", "Every normalized fact must cite an evidence_span copied character for character from the current customer message. Normalizing does not loosen this: the value may be a canonical term the customer never typed, but the span is always their own words.", "When expected_answer_field_key is set and the customer replies to it, decide what their message means for that field instead of looking for a phrase you recognise. For a field whose validation.mode is enum, pick the single entry of validation.values whose meaning the answer expresses and emit that entry's canonical value exactly as published. The aliases beside each value are examples of how customers say it, not a closed list: a one-word, misspelled, unaccented, negated or paraphrased answer counts just the same. For an enum field never emit the customer's raw words as the value, and never emit a value that is not in validation.values; a field whose validation.mode is not enum keeps taking the customer's own words.", "Only a genuine tie is ambiguous. If the message fits two published values equally well, emit no fact for that field and ask one short question that separates them; do not guess. Silence about a field the customer just answered is worse than either -- it leaves the branch open and lets the other branch's prices reach them.", "When no branch is active, selecting one is your job. If origin.ref matches a rule in policy.rules.branch_selection.origin_binding, select that branch at once and never ask the selection question. Otherwise classify the answer to the selection field the same semantic way and emit branch_selections with action=select and the branch_anchor_node_id that the value you chose belongs to. The customer never has to name the branch or repeat a published term for you to select it. Only a genuine tie between branches justifies selecting none, and then you ask the one question that separates them.", "Once a branch is active, keep it. Only a trigger declared in policy.rules.branch_selection.stability may switch it; a word used to answer a qualification field is never a branch change.", "Never mix one branch with another. State only the prices, minimums, conditions and positioning of the active branch. approved_nodes and approved_chunks already exclude every other branch, so anything outside them is not yours to say.", "Use only published evidence for commercial claims.", "Never promise an action the backend has not performed: no sending photos, files or links, no callbacks, no promise to do something now, unless the published policy declares that capability.", "For photos, offer help only when approved_nodes or approved_chunks explicitly prove an approved image for the exact product and the published content-delivery policy permits the offer. Without that evidence, do not mention photos unless the customer explicitly asks; then use the published human-follow-up response and request handoff.", "Treat freight cost and delivery timing as specialist-confirmed unless explicit published evidence authorizes an exact claim. You may record whether the customer prefers shipping or a store visit.", "Whenever handoff_requested is true, the same public reply must first tell the customer that a human will continue, using the published handoff notice. A conversational handoff is never silent.", "If the facts extracted in this envelope together with facts_by_key resolve every required field in graph_contract.fields, qualification completes on this turn. Do not ask a catalog, product-detail or consultative question. Briefly summarize what was collected and ask only the published policy.rules.qualification.confirmation_question; keep asked_field_key null and handoff_requested false until the customer answers. When pending_confirmation_ref is non-null, an unqualified yes or no refers only to that pending confirmation, never to a product mentioned in the prior reply. On an affirmative answer, set confirmation.state=affirm, confirmation.target_ref exactly to pending_confirmation_ref, handoff_requested=true and use the published completion and pre-handoff notice in the reply without another question. A bare confirmation is valid only for pending_confirmation_ref.", "Return one public reply string. The backend will preserve it byte for byte."], rules: conversationPolicy }, isolation: { persona_slug: context.persona_slug, agent_slug: context.agent_slug, publication_version: context.graph_version, publication_checksum: context.graph_checksum }, customer_message: binding.message, is_first_assistant_turn: isFirstAssistantTurn, origin: { ref: binding.origin_ref || null }, source_message_id: binding.external_message_id, recent_messages: memory.recent_messages, facts_by_key: factsByKey, expected_answer_field_key: expectedAnswerFieldKey, pending_confirmation_ref: context.pending_confirmation_ref || null, asked_field_keys: askedFieldKeys, do_not_ask_field_keys: doNotAskFieldKeys, active_branch_node_id: context.active_branch_node_id, active_branch_node_ids: context.active_branch_node_ids || [], branch_candidates: context.retrieval_trace && context.retrieval_trace.branch_candidates || [], graph_contract: { branch_anchor_node_id: contract.branch_anchor_node_id || null, fields: fields, completion: contract.completion || {}, handoff: contract.handoff || {}, commercial_limits: contract.commercial_limits || contract.claim_policy || {} }, approved_nodes: approvedNodes, approved_chunks: approvedChunks };
