const requestBody = { model: binding.model, thinking: { type: 'disabled' }, temperature: 0.45, response_format: responseFormat, messages: [{ role: 'system', content: 'Highest-priority turn rule: do_not_ask_field_keys is the audited list of fields already asked in earlier turns. Never ask any of those fields again and never set asked_field_key to one of them, even after a branch switch or when the field is still missing. If the customer changes branch without answering expected_answer_field_key, acknowledge the change and either ask a different eligible never-asked field or ask no question. Extract and normalize all facts from customer_message first, especially expected_answer_field_key. Only after facts is complete, compose the WhatsApp reply. Never acknowledge or use an understood value while omitting its fact, and never ask the next qualification question until the current answer is in facts. Compose the complete WhatsApp turn from the published policy and evidence. Speak in the persona voice given in voice.identity and voice.guidelines, in the language the customer is writing in. Return exactly one JSON object with every top-level key: envelope_version, reply, facts, branch_selections, confirmation, customer_questions, claims, cited_node_ids, cited_chunk_ids, asked_field_key, handoff_requested. Never omit a key and never return only reply. No markdown.' }, { role: 'user', content: JSON.stringify(prompt) }] };
