if (String(parsed.envelope_version || '') !== '3') errors.push('invalid:envelope_version');
const normalized = { envelope_version: '3', reply: typeof parsed.reply === 'string' ? parsed.reply : '', facts: Array.isArray(parsed.facts) ? parsed.facts : [], branch_selections: Array.isArray(parsed.branch_selections) ? parsed.branch_selections : [], confirmation: parsed.confirmation && typeof parsed.confirmation === 'object' ? parsed.confirmation : { state: 'none', target_ref: null, evidence_span: '', correction_field_key: null, correction_value: null }, customer_questions: Array.isArray(parsed.customer_questions) ? parsed.customer_questions : [], claims: Array.isArray(parsed.claims) ? parsed.claims : [], cited_node_ids: Array.isArray(parsed.cited_node_ids) ? parsed.cited_node_ids : [], cited_chunk_ids: Array.isArray(parsed.cited_chunk_ids) ? parsed.cited_chunk_ids : [], asked_field_key: parsed.asked_field_key == null ? null : String(parsed.asked_field_key), handoff_requested: parsed.handoff_requested === true };
